/**
 * The golden corpus: 29 inputs made from lavfi sources only, plus two copies (a 32 kHz resample of the mono
 * speech and a file whose name has spaces and non-ASCII characters). The attachment is a generated byte file,
 * so nothing depends on system fonts or media. Every file is written under the folder the caller names.
 */
import { copyFile, mkdir, readFile, rm, stat, writeFile } from 'node:fs/promises'
import { cpus } from 'node:os'
import { join } from 'node:path'
import { LAYOUT_CHANNELS, lf, loudnessArgs, parseAstatsOverall, readLoudness, runTool } from './oracle'

/** Raised when a generator command changes, so a corpus built by older commands is rebuilt. */
export const CORPUS_REV = 1

/** The name of the manifest written beside the corpus files. */
export const MANIFEST = 'corpus.json'

/** The streams ffprobe must report for a corpus file. */
export interface CorpusShape
{
  /** Channel count of each audio stream, in order. */
  channels: readonly number[]
  /** Channel layout of each audio stream, where it matters. */
  layouts?: readonly string[]
  sampleRate?: number
  video?: number
  subtitles?: number
  attachments?: number
  chapters?: number
}

/** What a generator can use. */
export interface CorpusContext
{
  readonly ffmpeg: string
  readonly encoders: ReadonlySet<string>
  /** A path in the corpus folder. */
  out(name: string): string
  /** A path in the scratch folder for intermediates. */
  tmp(name: string): string
  /** Runs ffmpeg at `-v error` with `-y`; rejects on a non-zero exit. */
  ff(args: readonly string[]): Promise<void>
  /** Builds an intermediate once, however many generators ask for it. */
  once(key: string, make: () => Promise<void>): Promise<void>
  /** Waits for another corpus entry. */
  entry(name: string): Promise<void>
}

/** One corpus input. */
export interface CorpusEntry
{
  name: string
  role: string
  /** A copy of another input rather than one of the 29 inputs. */
  copy?: boolean
  /** Encoders the entry cannot be made without; a build that lacks one leaves the entry out. */
  needs?: readonly string[]
  shape: CorpusShape
  build(c: CorpusContext): Promise<void>
}

const PCM_F32 = ['-c:a', 'pcm_f32le'] as const
const PCM_S16 = ['-c:a', 'pcm_s16le'] as const
const PCM_S24 = ['-c:a', 'pcm_s24le'] as const

/** Stereo program bed: two pink-noise channels plus a bass, mid, and treble tone layer. */
function bed(rate: number, seconds: number, seedA: number, seedB: number): string
{
  return `anoisesrc=color=pink:sample_rate=${rate}:amplitude=0.35:seed=${seedA}:duration=${seconds}[nA];` +
    `anoisesrc=color=pink:sample_rate=${rate}:amplitude=0.35:seed=${seedB}:duration=${seconds}[nB];` +
    '[nA][nB]join=inputs=2:channel_layout=stereo[nz];' +
    `aevalsrc=exprs='0.25*sin(2*PI*55*t)+0.12*sin(2*PI*220*t)*(0.6+0.4*sin(2*PI*0.5*t))+0.06*sin(2*PI*1760*t)':s=${rate}:d=${seconds}:c=stereo[tn];` +
    '[nz][tn]amix=inputs=2:normalize=0'
}

/** Independent pink noise on the active channels of a layout and digital silence on the rest. */
function layoutNoise(layout: string, active: readonly string[], seconds: number, seed: number, amplitude: number): string
{
  const names = LAYOUT_CHANNELS[layout]
  const sources = names.map((name, i) => active.includes(name)
    ? `anoisesrc=color=pink:sample_rate=48000:amplitude=${amplitude}:seed=${seed + i}:duration=${seconds}[c${i}]`
    : `anullsrc=r=48000:cl=mono,atrim=duration=${seconds}[c${i}]`)
  const inputs = names.map((_, i) => `[c${i}]`).join('')
  const map = names.map((name, i) => `${i}.0-${name}`).join('|')
  return `${sources.join(';')};${inputs}join=inputs=${names.length}:channel_layout=${layout}:map=${map}`
}

async function render(c: CorpusContext, graph: string, out: string, codec: readonly string[] = PCM_F32): Promise<void>
{
  await c.ff(['-filter_complex', `${graph}[out]`, '-map', '[out]', ...codec, out])
}

async function integrated(c: CorpusContext, file: string): Promise<number>
{
  const run = await runTool(c.ffmpeg, loudnessArgs(file))
  if (run.code !== 0) throw new Error(`Measuring ${file} exited with ${run.code}`)
  const reading = readLoudness(run.stderr)
  return reading.integratedPrecise ?? reading.integrated
}

async function peakDb(c: CorpusContext, file: string): Promise<number>
{
  const run = await runTool(c.ffmpeg, ['-hide_banner', '-nostdin', '-nostats', '-v', 'info', '-i', file,
    '-filter_complex', '[0:a:0]astats@o=measure_perchannel=none[m]', '-map', '[m]', '-f', 'null', '-'])
  const peak = parseAstatsOverall(run.stderr)['Peak level dB']
  if (run.code !== 0 || peak === undefined || !Number.isFinite(peak)) throw new Error(`No sample peak for ${file}`)
  return peak
}

async function gainTo(c: CorpusContext, input: string, output: string, gainDb: number, codec: readonly string[], pre = '', post = ''): Promise<void>
{
  const chain = [pre, `volume=${gainDb.toFixed(3)}dB`, post].filter(Boolean).join(',')
  await c.ff(['-i', input, '-af', chain, ...codec, output])
}

/** Renders a raw bed, then adjusts gain until the output measures within `tolerance` LU of `target`. */
async function levelTo(c: CorpusContext, raw: string, out: string, target: number, tolerance: number, codec: readonly string[], post = '', headroom = 0): Promise<void>
{
  let gain = target - await integrated(c, raw) + headroom
  for (let i = 0; i < 5; i++)
  {
    await gainTo(c, raw, out, gain, codec, '', post)
    const measured = await integrated(c, out)
    if (Math.abs(measured - target) < tolerance) return
    gain += (target - measured) * (post ? 1.3 : 1)
  }
}

const STAIRCASE = "volume='if(lt(mod(t,30),5),1,if(lt(mod(t,30),10),0.5,if(lt(mod(t,30),15),0.25,if(lt(mod(t,30),20),0.125,if(lt(mod(t,30),25),0.0316,0.01)))))':eval=frame"

const FILM = (seconds: number): string =>
  `anoisesrc=color=pink:sample_rate=48000:amplitude=0.05:seed=11:duration=${seconds},volume='if(lt(mod(t,15),2),10,1)':eval=frame[fl];` +
  `anoisesrc=color=pink:sample_rate=48000:amplitude=0.05:seed=12:duration=${seconds},volume='if(lt(mod(t,15),2),10,1)':eval=frame[fr];` +
  `anoisesrc=color=pink:sample_rate=48000:amplitude=0.6:seed=13:duration=${seconds},highpass=f=200,lowpass=f=4000,volume='(0.55+0.45*sin(2*PI*4*t))*if(lt(mod(t,6),4.5),0.5,0.01)':eval=frame[fc];` +
  `aevalsrc=exprs='0.25*sin(2*PI*40*t)*if(lt(mod(t,15),2),1,0.1)':s=48000:d=${seconds}[lfe];` +
  `anoisesrc=color=pink:sample_rate=48000:amplitude=0.03:seed=14:duration=${seconds},volume='if(lt(mod(t,15),2),12,1)':eval=frame[sl];` +
  `anoisesrc=color=pink:sample_rate=48000:amplitude=0.03:seed=15:duration=${seconds},volume='if(lt(mod(t,15),2),12,1)':eval=frame[sr];` +
  '[fl][fr][fc][lfe][sl][sr]join=inputs=6:channel_layout=5.1(side):map=0.0-FL|1.0-FR|2.0-FC|3.0-LFE|4.0-SL|5.0-SR'

const SUBTITLES = '1\r\n00:00:01,000 --> 00:00:03,000\r\nFirst cue\r\n\r\n2\r\n00:00:04,000 --> 00:00:06,000\r\nSecond cue\r\n\r\n' +
  '3\r\n00:00:07,000 --> 00:00:09,000\r\nThird cue\r\n'

const CHAPTERS = ';FFMETADATA1\ntitle=Golden Clip\nartist=molexMedia\n\n[CHAPTER]\nTIMEBASE=1/1000\nSTART=0\nEND=5000\ntitle=Part One\n\n' +
  '[CHAPTER]\nTIMEBASE=1/1000\nSTART=5000\nEND=10000\ntitle=Part Two\n'

const TAGS = ['-metadata', 'title=Cover Test', '-metadata', 'artist=molexMedia', '-metadata', 'album=Golden Album'] as const

/** A deterministic byte file attached as a font; MKV stores attachments without reading them. */
export function fontBytes(): Buffer
{
  const bytes = Buffer.alloc(4096)
  bytes.write('\u0000\u0001\u0000\u0000', 0, 'latin1')
  for (let i = 4; i < bytes.length; i++) bytes[i] = (i * 31 + 7) & 0xff
  return bytes
}

function videoCodec(c: CorpusContext): string[]
{
  return c.encoders.has('libx264')
    ? ['-c:v', 'libx264', '-preset', 'ultrafast', '-crf', '30', '-pix_fmt', 'yuv420p']
    : ['-c:v', 'mpeg4', '-q:v', '8', '-pix_fmt', 'yuv420p']
}

async function film(c: CorpusContext): Promise<string>
{
  const raw = c.tmp('film_raw.wav')
  await c.once('film', () => render(c, FILM(30), raw))
  return raw
}

async function programA0(c: CorpusContext): Promise<string>
{
  const raw = c.tmp('a0_raw.wav')
  const out = c.tmp('a0.wav')
  await c.once('a0', async () =>
  {
    await render(c, bed(48000, 10, 21, 22), raw)
    await levelTo(c, raw, out, -14, 0.5, PCM_F32, 'alimiter=limit=0.891:level=disabled:latency=1')
  })
  return out
}

async function sidecars(c: CorpusContext): Promise<{ subs: string; chapters: string; font: string; cover: string }>
{
  const files = { subs: c.tmp('subs.srt'), chapters: c.tmp('chapters.txt'), font: c.tmp('molex-test.ttf'), cover: c.tmp('cover.png') }
  await c.once('sidecars', async () =>
  {
    await writeFile(files.subs, SUBTITLES)
    await writeFile(files.chapters, CHAPTERS)
    await writeFile(files.font, fontBytes())
    await c.ff(['-f', 'lavfi', '-i', 'color=c=red:s=320x320', '-frames:v', '1', files.cover])
  })
  return files
}

